function clone(value){return JSON.parse(JSON.stringify(value));}
function loadState(){try{const value=JSON.parse(localStorage.getItem(KEY));if(value&&value.accounts&&value.policies&&value.claims)return value;}catch{}return null;}
let state=loadState()||clone(seed);
let timer;
const $=selector=>document.querySelector(selector);
function esc(value){return String(value==null?'':value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function cash(value){return '$'+(Number(value)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function whole(value){return '$'+(Number(value)||0).toLocaleString('en-US',{maximumFractionDigits:0});}
function date(value){return new Date(value+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable.');}}
function toast(text){const node=$('#toast');node.textContent=text;node.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>node.classList.remove('show'),2400);}
function account(){return state.accounts.find(x=>x.id===state.selectedAccountId)||state.accounts[0];}
function policyFor(accountId){return state.policies.find(x=>x.accountId===accountId);}
function accountFor(id){return state.accounts.find(x=>x.id===id);}
function badge(text){const s=String(text||'Open');const cls=/past due|declined|denied|blocked/i.test(s)?'red':/requested|review|progress|due|pending|modified|at risk/i.test(s)?'gold':/paid|accepted|complete|in force|approved|cleared|closed|quoted/i.test(s)?'green':'blue';return '<span class="badge '+cls+'">'+esc(s)+'</span>';}
function btn(text,action,cls){return '<button class="btn '+(cls||'')+'" data-action="'+esc(action)+'">'+text+'</button>';}
function table(head,rows){return '<div class="table-wrap"><table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';}
function rolesNav(){return D.getRoleNavigation(state.role);}
function icon(id){return ({dashboard:'⌂',account:'▣',policy:'▤',submissions:'⇢',claims:'✚',billing:'＄',audits:'◫',products:'⚙',qa:'✓'})[id]||'•';}
function navLabel(id){return ({dashboard:'Work queue',account:'Employer account',policy:'PolicyCenter',submissions:'Producer submissions',claims:'ClaimCenter',billing:'BillingCenter',audits:'Premium audit',products:'Product configuration',qa:'QA workbench'})[id];}
function nav(){const ids=rolesNav().map(x=>x[0]);const groups=[['Workspace',['dashboard','account','policy']],['Transactions',['submissions','claims','billing','audits']],['Configuration & assurance',['products','qa']]];return groups.map(g=>{const shown=g[1].filter(id=>ids.includes(id)&&id!=='dashboard');if(!shown.length)return '';return '<div class="navgroup"><div class="navlabel">'+g[0]+'</div>'+shown.map(id=>'<button class="navitem '+(state.view===id?'active':'')+'" data-view="'+id+'"><span class="navicon">'+icon(id)+'</span><span>'+navLabel(id)+'</span></button>').join('')+'</div>';}).join('');}
function head(title,description,action){return '<div class="viewhead"><div><div class="eyebrow">'+esc(state.role)+' workspace</div><h1>'+title+'</h1><p class="subhead">'+description+'</p></div>'+(action||'')+'</div>';}
function stat(label,value,note){return '<div class="card stat"><div class="stat-label">'+label+'</div><div class="stat-value">'+value+'</div><div class="stat-note">'+note+'</div></div>';}
function shell(){const role=ROLES[state.role];return '<div class="layout"><aside id="sidebar" class="sidebar"><a class="brand" href="#" data-view="dashboard"><span class="brandmark">WC</span><span><span class="brandname">'+APP+'</span><span class="brandmeta">Workers compensation · California</span></span></a><button class="navitem '+(state.view==='dashboard'?'active':'')+'" data-view="dashboard"><span class="navicon">⌂</span><span>Work queue</span></button>'+nav()+'<div class="sidefoot"><strong>InsuranceSuite workflow model</strong>PolicyCenter · ClaimCenter · BillingCenter<br>Connected local training workspace</div></aside><section class="main"><header class="topbar"><div class="row"><button class="btn mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div class="crumb">'+APP+' › <strong>'+esc(navLabel(state.view)||'Alerts')+'</strong></div></div><div class="topright"><button class="btn" data-view="notifications">Alerts <span class="badge gold">'+state.events.length+'</span></button><select class="role-switch" data-field="role" aria-label="Switch user role">'+Object.keys(ROLES).map(r=>'<option '+(r===state.role?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select><div class="avatar" title="'+esc(role.name)+'">'+role.initials+'</div></div></header><main class="content" id="main">'+page()+'</main></section></div>';}
function landing(){return '<div class="landing"><div class="landing-inner"><div class="landing-brand"><span class="brandmark">WC</span><div><h2>'+APP+'</h2><p>Workers compensation policy, claims and billing workflows</p></div></div><section class="hero"><div class="eyebrow">Guidewire InsuranceSuite learning workspace</div><h1>One employer account. A connected workers compensation lifecycle.</h1><p>Follow realistic submissions, underwriting decisions, policy transactions, payroll reports, premium audits, invoices and injury claims across the people who manage them.</p><div class="toolbar">'+btn('Open the workspace →','open-workspace','primary')+btn('View current work queue','open-workspace','')+'</div><div class="notice blue" style="margin-top:17px">The seeded scenario follows Sierra Peak Machine Works through a 2027 renewal review. Actions in one role update shared records, alerts and the next role’s queue.</div></section><div class="hero-grid"><section class="hero-side"><h2>Try a role-based workflow</h2><div class="role-card-grid">'+[['Producer','Prepare renewal and new-business submissions'],['Underwriter','Review referrals, evidence and quote decisions'],['Employer','Review policies, payroll and injury reports'],['Claims Adjuster','Manage claims and return to work'],['Billing Specialist','Work invoices and payment status'],['Premium Auditor','Reconcile estimated and actual payroll'],['Injured Worker','View claim status and next steps'],['Product Admin','Review class codes and product controls']].map(x=>'<button class="role-card" data-role-card="'+x[0]+'"><strong>'+x[0]+'</strong><span>'+x[1]+'</span></button>').join('')+'</div><div class="tiny">Use the role switcher to move between connected work queues.</div></section><section class="hero-side"><h2>Guidewire-aligned work areas</h2>'+[['PolicyCenter','Submission, rating, underwriting, policy changes, renewal and audit scheduling'],['ClaimCenter','First notice, assignment, coverage review, reserves and return to work'],['BillingCenter','Invoices, installment plans, receipts and delinquency follow-up']].map(x=>'<div class="list-item"><div class="list-main"><strong>'+x[0]+'</strong><span>'+x[1]+'</span></div></div>').join('')+'<p class="tiny">PolicyCenter supports workers compensation premium report and final audit jobs. <a target="_blank" rel="noopener" href="https://docs.guidewire.com/cloud/is/202603/cloudapibf/cloudAPI/PolicyCenter/job-types/audits.html">Guidewire audit reference ↗</a></p></section></div><footer>All sample businesses, people, policies, claims, payroll and decisions are fictional. Sample rates and estimates are illustrative.</footer></div></div>';}
function page(){if(state.view==='welcome')return landing();if(state.view==='account')return accountPage();if(state.view==='policy')return policyPage();if(state.view==='submissions')return submissionsPage();if(state.view==='claims')return claimsPage();if(state.view==='billing')return billingPage();if(state.view==='audits')return auditPage();if(state.view==='products')return productsPage();if(state.view==='qa')return qaPage();if(state.view==='notifications')return alertsPage();return dashboard();}
function render(){document.title=APP+(state.view==='welcome'?'':' · '+(navLabel(state.view)||'Alerts'));$('#app').innerHTML=state.view==='welcome'?landing():shell();}
function open(view){const allowed=rolesNav().map(x=>x[0]);state.view=allowed.includes(view)||view==='notifications'||view==='welcome'?view:'dashboard';save();render();}
function push(title,detail,accountId){state.events.unshift({time:new Date().toISOString().slice(0,16).replace('T',' '),title,detail,accountId:accountId||state.selectedAccountId});}
function accountRows(){return state.accounts.map(a=>{const p=policyFor(a.id);return '<tr><td><strong>'+esc(a.name)+'</strong><small>'+esc(a.address)+'</small></td><td>'+esc(a.industry)+'</td><td>'+a.employees+'</td><td>'+p.id+'</td><td>'+date(a.renewal)+'</td><td>'+btn(a.id===state.selectedAccountId?'Selected':'Open','account:'+a.id,a.id===state.selectedAccountId?'soft small':'small')+'</td></tr>';}).join('');}
function dashboard(){const openClaims=state.claims.filter(c=>c.status!=='Closed').length;const openSubs=state.submissions.filter(s=>!['Issued','Declined'].includes(s.status)).length;const pastDue=state.invoices.filter(i=>i.status==='Past due').length;const openAudit=state.audits.filter(a=>a.status==='In progress').length;let stats=[stat('Active policies',state.policies.filter(p=>p.status==='In force').length,'Current workers compensation terms'),stat('Open submissions',openSubs,'New business and renewal work'),stat('Open claims',openClaims,'Connected employer accounts'),stat('Upcoming renewals',state.policies.filter(p=>p.status==='In force'&&p.end<='2027-03-01').length,'Renewal work scheduled through Mar 1')];if(state.role==='Billing Specialist')stats=[stat('Past-due accounts',pastDue,'Billing follow-up required'),stat('Open balance',whole(state.invoices.reduce((n,i)=>n+i.billed-i.paid,0)),'All sample accounts'),stat('Invoices',state.invoices.length,'Installments and audit entries'),stat('Policies billed',state.policies.filter(p=>p.status==='In force').length,'Active BillingCenter account links')];if(state.role==='Premium Auditor')stats=[stat('Open audits',openAudit,'Payroll verification required'),stat('Employer accounts',state.accounts.length,'Audit inventory'),stat('Payroll classes',new Set(account().payroll.map(x=>x.code)).size,'Selected employer'),stat('Due this week',1,'Next review Nov 21')];const queue=queueSummary();const events=state.events.slice(0,5).map(e=>'<div class="event"><strong>'+esc(e.title)+'</strong><p>'+esc(e.time)+' · '+esc(e.detail)+'</p></div>').join('');return head('Work queue','Welcome, '+esc(ROLES[state.role].name)+'. Review the work and handoffs that need attention today.',btn('Open employer account','go:account'))+'<div class="grid cols4" style="margin-bottom:14px">'+stats.join('')+'</div><div class="grid cols2"><section class="card"><div class="card-head"><div><h2>'+queue.title+'</h2><p>'+queue.note+'</p></div>'+badge(queue.rows.length?'Needs attention':'Clear')+'</div>'+queue.html+'</section><section class="card"><div class="card-head"><div><h2>Recent activity</h2><p>Shared activity across roles</p></div><button class="btn small" data-view="notifications">View alerts</button></div><div class="timeline">'+events+'</div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Connected employer accounts</h2><p>Open an account to follow policy, claims, billing and audit records.</p></div></div>'+table(['Employer','Business','Employees','Policy','Renewal','Account'],accountRows())+'</section>';}
function queueSummary(){let rows=[],title='My assigned work',note='Role-based items from the connected records.';if(state.role==='Underwriter'){rows=state.submissions.filter(s=>!['Issued','Declined'].includes(s.status));title='Underwriting referrals';}else if(state.role==='Producer'){rows=state.submissions;title='Producer submission pipeline';}else if(state.role==='Claims Adjuster'){rows=state.claims.filter(c=>c.status!=='Closed');title='Claims requiring follow-up';}else if(state.role==='Injured Worker'){rows=state.claims.filter(c=>c.workerId===ROLES[state.role].workerId);title='My claim and next steps';note='Your view shows status and work status information.';}else if(state.role==='Billing Specialist'){rows=state.invoices.filter(i=>i.status!=='Paid');title='Billing work queue';}else if(state.role==='Premium Auditor'){rows=state.audits.filter(a=>a.status==='In progress');title='Audit assignments';}else if(state.role==='Product Admin'){rows=state.products.rules.filter(r=>r.status!=='Active');title='Product control reviews';}else if(state.role==='Employer'){rows=state.events.slice(0,3);title='Employer follow-ups';}else {rows=state.events;title='Workspace activity';}const html=rows.length?rows.slice(0,5).map(x=>'<div class="list-item"><div class="list-main"><strong>'+esc(x.id||x.title||x.name)+'</strong><span>'+esc(x.referral||x.next||x.detail||x.note||x.value||x.status)+'</span></div>'+badge(x.priority||x.status||'Open')+'</div>').join(''):'<div class="notice green">No open work items in this role view.</div>';return {rows,title,note,html};}
function accountPage(){const a=account();const total=a.payroll.reduce((n,p)=>n+p.estimated,0);const payroll=a.payroll.map(p=>'<tr><td><strong>'+p.code+'</strong><small>'+esc(p.description)+'</small></td><td>'+p.state+'</td><td>'+whole(p.estimated)+'</td><td>'+whole(p.actual)+'</td><td>'+cash(p.rate)+'</td><td>'+whole(D.manualPremium(p.estimated,p.rate,1))+'</td></tr>').join('');const loc=a.locations.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong><small>'+esc(x.address)+'</small></td><td>'+x.classCode+'</td><td>'+x.employees+'</td><td>'+whole(x.payroll)+'</td></tr>').join('');const opts=state.accounts.map(x=>'<option value="'+x.id+'" '+(x.id===a.id?'selected':'')+'>'+esc(x.name)+'</option>').join('');return head('Employer account','Account facts, locations, payroll exposure and loss history used across policy, underwriting and audit.', ['Employer','Producer','System Administrator'].includes(state.role)?btn('Submit payroll update','payroll','primary'):'')+'<div class="toolbar" style="margin-bottom:13px"><label class="tiny">Selected employer</label><select class="role-switch" data-field="account">'+opts+'</select>'+badge(a.safetyStatus)+'</div><div class="grid cols3" style="margin-bottom:14px">'+stat('Legal entity',esc(a.name),'DBA '+esc(a.dba))+stat('Employees',a.employees,'Across '+a.locations.length+' locations')+stat('Estimated annual payroll',whole(total),'Experience mod '+a.experienceMod.toFixed(2))+'</div><div class="grid cols2"><section class="card"><div class="card-head"><div><h2>Account profile</h2><p>Producer and underwriting reference</p></div>'+badge('Active')+'</div><div class="list-item"><div class="list-main"><strong>Federal employer ID</strong><span>'+esc(a.fein)+'</span></div><div class="list-main"><strong>Years in business</strong><span>'+a.years+'</span></div></div><div class="list-item"><div class="list-main"><strong>Primary address</strong><span>'+esc(a.address)+'</span></div></div><div class="list-item"><div class="list-main"><strong>Operations</strong><span>'+esc(a.industry)+'</span></div></div><div class="list-item"><div class="list-main"><strong>Producer</strong><span>'+esc(a.broker)+'</span></div></div><div class="notice blue">'+esc(a.safety)+'</div></section><section class="card"><div class="card-head"><div><h2>Locations &amp; class exposure</h2><p>Payroll shown by location and classification</p></div></div>'+table(['Location','Class code','Employees','Payroll estimate'],loc)+'</section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Payroll by classification</h2><p>Annual estimates and reported payroll</p></div>'+((state.role==='Employer')?btn('Send update to producer','send-payroll','small'):'')+'</div>'+table(['Class code & description','State','Estimated payroll','Reported payroll','Sample rate / $100','Manual estimate'],payroll)+'<p class="tiny">Classification assignment follows actual duties and current state rules. Rates shown are training assumptions.</p></section><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Policy loss history</h2><p>Claim records used in renewal discussion</p></div>'+btn('Open ClaimCenter','go:claims','small')+'</div>'+table(['Claim','Date','Worker','Incurred','Status'],state.claims.filter(c=>c.accountId===a.id).map(c=>'<tr><td>'+c.id+'</td><td>'+date(c.injuryDate)+'</td><td>'+esc(c.worker)+'</td><td>'+whole(c.reserve)+'</td><td>'+badge(c.status)+'</td></tr>').join(''))+'</section>';}
function policyPage(){const a=account(),p=policyFor(a.id),estimate=D.policyEstimate(a.payroll,a.experienceMod,a.credit);const classes=a.payroll.map(x=>'<tr><td><strong>'+x.code+'</strong><small>'+esc(x.description)+'</small></td><td>'+x.state+'</td><td>'+whole(x.estimated)+'</td><td>'+cash(x.rate)+'</td><td>'+whole(D.manualPremium(x.estimated,x.rate,1))+'</td></tr>').join('');return head('PolicyCenter','Submission, underwriting, policy term, transactions, renewal and premium audit schedule.',['Producer','Employer','System Administrator'].includes(state.role)?btn('Start renewal submission','start-renewal','primary'):'')+'<div class="grid cols4" style="margin-bottom:14px">'+stat('Policy number',p.id,'Workers compensation · California')+stat('Policy term',date(p.start)+' – '+date(p.end),'One-year term')+stat('Annual premium',whole(p.premium),p.billing+' billing')+stat('Experience modification',a.experienceMod.toFixed(2),'Validate rating worksheet')+'</div><div class="grid cols2"><section class="card"><div class="card-head"><div><h2>Policy details</h2><p>'+esc(a.name)+' · '+esc(a.industry)+'</p></div>'+badge(p.status)+'</div><div class="list-item"><div class="list-main"><strong>Named insured</strong><span>'+esc(a.name)+' · EIN '+esc(a.fein)+'</span></div><div class="list-main"><strong>Renewal status</strong><span>'+esc(p.renewalStatus)+'</span></div></div><div class="list-item"><div class="list-main"><strong>Underwriter</strong><span>'+esc(p.underwriter)+'</span></div><div class="list-main"><strong>Premium audit</strong><span>'+esc(p.auditStatus)+'</span></div></div><div class="notice blue">Current transaction: '+esc(p.transaction)+'. Policy changes preserve effective dates and transaction history.</div><div class="toolbar" style="margin-top:12px">'+btn('Request policy change','endorsement','small')+btn('Open premium audit','go:audits','small')+'</div></section><section class="card"><div class="card-head"><div><h2>Illustrative premium estimate</h2><p>Payroll × training rate, adjusted by experience mod</p></div>'+badge('Illustrative')+'</div>'+table(['Class','State','Payroll','Rate / $100','Manual premium'],classes)+'<div class="list-item"><strong>Manual premium</strong><b>'+whole(estimate.manual)+'</b></div><div class="list-item"><strong>Experience adjusted</strong><b>'+whole(estimate.modified)+'</b></div><div class="list-item"><strong>Schedule credit</strong><b>−'+whole(estimate.credit)+'</b></div><div class="row"><strong>Indicative annual premium</strong><strong>'+whole(estimate.estimated)+'</strong></div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Renewal milestones</h2><p>Connected producer and underwriting work</p></div></div>'+table(['Milestone','Owner','Due','Status'],'<tr><td>Collect payroll and employee count</td><td>Producer + Employer</td><td>Dec 1, 2026</td><td>'+badge(p.renewalStatus)+'</td></tr><tr><td>Resolve loss-history and safety referral</td><td>Underwriter</td><td>Dec 8, 2026</td><td>'+badge('In review')+'</td></tr><tr><td>Issue renewal offer</td><td>Underwriter + Producer</td><td>Dec 15, 2026</td><td>'+badge('Planned')+'</td></tr>')+'</section>';}
function submissionsPage(){const uw=['Underwriter','System Administrator'].includes(state.role);const rows=state.submissions.map(s=>{const a=accountFor(s.accountId);let actions='';if(uw&&['Submitted','Information requested','Underwriter review'].includes(s.status))actions=btn('Request info','submission-info:'+s.id,'small')+btn('Clear to quote','submission-clear:'+s.id,'small primary')+btn('Decline','submission-decline:'+s.id,'small danger');else if(state.role==='Producer'&&s.status==='Information requested')actions=btn('Confirm evidence received','submission-evidence:'+s.id,'small');else actions='<span class="tiny">No action pending</span>';return '<tr><td><strong>'+s.id+'</strong><small>'+s.type+' · '+date(s.received)+'</small></td><td>'+esc(a.name)+'<small>Effective '+s.effective+'</small></td><td>'+esc(s.producer)+'</td><td>'+esc(s.owner)+'</td><td>'+badge(s.status)+'</td><td>'+esc(s.referral)+'</td><td><div class="toolbar">'+actions+'</div></td></tr>';}).join('');return head(uw?'Underwriting workbench':'Producer submissions',uw?'Review duties, payroll, loss history and evidence before making a quote decision.':'Manage new-business and renewal submissions, evidence and producer follow-up.',state.role==='Producer'?btn('Create submission','new-submission','primary'):'')+'<div class="grid cols3" style="margin-bottom:14px">'+stat('Submissions',state.submissions.length,'New business and renewals')+stat('Underwriter review',state.submissions.filter(s=>['Submitted','Underwriter review'].includes(s.status)).length,'Current decision queue')+stat('Information requested',state.submissions.filter(s=>s.status==='Information requested').length,'Producer follow-up')+'</div><section class="card"><div class="card-head"><div><h2>'+(uw?'Submission decision queue':'Submission pipeline')+'</h2><p>Role actions update shared records and alerts.</p></div></div>'+table(['Submission','Employer & effective date','Producer','Underwriter','Status','Referral / note','Action'],rows)+'</section><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Underwriting review checklist</h2><p>Review before clearing a referral</p></div></div><div class="grid cols3"><div class="notice blue">Check class assignment against actual operations and duties.</div><div class="notice blue">Compare payroll by state, location and class code.</div><div class="notice blue">Review loss runs, safety controls and open claim exposure.</div></div></section>';}
function claimRows(list){return list.map(c=>'<tr><td><strong>'+c.id+'</strong><small>'+c.policyId+'</small></td><td>'+esc(c.worker)+'<small>'+esc(c.job)+'</small></td><td>'+date(c.injuryDate)+'</td><td>'+badge(c.status)+'</td><td>'+whole(c.reserve)+'</td><td>'+btn('Open','claim:'+c.key,'small')+'</td></tr>').join('');}
function claimsPage(){const worker=state.role==='Injured Worker',employer=state.role==='Employer',canAdjust=['Claims Adjuster','System Administrator'].includes(state.role);let list=state.claims;if(worker)list=list.filter(c=>c.workerId===ROLES[state.role].workerId);if(employer)list=list.filter(c=>c.accountId===state.selectedAccountId);let c=list.find(x=>x.key===state.activeClaimKey)||list[0];if(worker){if(!c)return head('My claim','No claim record is linked to this worker.');return head('My claim','Claim status, work information and next steps.')+'<section class="claim-banner"><div class="row"><div><div class="eyebrow">Claim '+c.id+'</div><h2>'+esc(c.status)+'</h2></div>'+badge(c.severity)+'</div><p>Injury date '+date(c.injuryDate)+' · Adjuster '+esc(c.adjuster)+'</p></section><div class="grid cols2" style="margin-top:14px"><section class="card"><h2>Claim updates</h2><div class="timeline" style="margin-top:13px">'+c.events.map(e=>'<div class="event"><strong>'+esc(e.title)+'</strong><p>'+date(e.date)+' · '+esc(e.detail)+'</p></div>').join('')+'</div></section><section class="card"><h2>Work status &amp; next step</h2><p class="notice blue" style="margin-top:12px">'+esc(c.rtw)+'</p><p class="small">'+esc(c.workerMessage)+'</p><p class="tiny">Follow your treating provider’s instructions and contact your employer or claims administrator with questions.</p></section></div>';}
if(employer)return head('ClaimCenter','Report an injury and follow employer-facing claim status and return-to-work requests.',btn('Report workplace injury','report-injury','primary'))+'<section class="card"><div class="card-head"><div><h2>Employer claim list</h2><p>'+esc(account().name)+'</p></div></div>'+table(['Claim','Worker','Injury date','Severity','Status','Employer follow-up'],list.map(x=>'<tr><td>'+x.id+'</td><td>'+esc(x.worker)+'</td><td>'+date(x.injuryDate)+'</td><td>'+x.severity+'</td><td>'+badge(x.status)+'</td><td>'+esc(x.employerMessage)+'</td></tr>').join(''))+'</section>';
if(!c)return head('ClaimCenter','No claims available to this role.');return head('ClaimCenter','Assigned claims, coverage confirmation, medical management, reserves and return-to-work coordination.')+'<div class="grid cols4" style="margin-bottom:14px">'+stat('Open claims',list.filter(x=>x.status!=='Closed').length,'Assigned employer accounts')+stat('Reserve exposure',whole(list.filter(x=>x.status!=='Closed').reduce((n,x)=>n+x.reserve,0)),'Current case reserves')+stat('Lost-time files',list.filter(x=>x.severity==='Lost time'&&x.status!=='Closed').length,'Active indemnity handling')+stat('Modified duty',list.filter(x=>x.status==='Modified duty').length,'Employer confirmation')+'</div><section class="card"><div class="card-head"><div><h2>Claim inventory</h2><p>Open a claim for file details and adjuster controls.</p></div></div>'+table(['Claim','Policy','Injured worker','Injury date','Status','Reserve','File'],claimRows(list))+'</section><section class="grid cols2" style="margin-top:14px"><div class="card"><div class="card-head"><div><h2>'+c.id+' · '+esc(c.worker)+'</h2><p>'+esc(accountFor(c.accountId).name)+' · '+esc(c.job)+'</p></div>'+badge(c.status)+'</div><div class="notice blue">'+esc(c.injury)+'</div><div class="list-item"><div><strong>Coverage</strong><small>'+esc(c.policyId)+' · active on injury date</small></div><div><strong>Provider</strong><small>'+esc(c.provider)+'</small></div></div><div class="list-item"><div><strong>Paid</strong><small>'+whole(c.paid)+'</small></div><div><strong>Lost days</strong><small>'+c.lostDays+'</small></div><div><strong>Reserve</strong><small>'+whole(c.reserve)+'</small></div></div><div class="notice">Return to work · '+esc(c.rtw)+'</div>'+(canAdjust?'<div class="toolbar" style="margin-top:11px">'+btn('Accept medical-only','claim-accept:'+c.key,'small')+btn('Confirm modified duty','claim-rtw:'+c.key,'small')+btn('Close claim','claim-close:'+c.key,'small danger')+'</div>':'')+'</div><div class="card"><h2>Claim event history</h2><div class="timeline" style="margin-top:13px">'+c.events.map(e=>'<div class="event"><strong>'+esc(e.title)+'</strong><p>'+date(e.date)+' · '+esc(e.detail)+'</p></div>').join('')+'</div></div></section>'+(canAdjust?'<section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Claim reserve update</h2><p>Record a revised estimate with a dated activity entry.</p></div></div><form id="reserveForm" class="toolbar"><input type="hidden" name="claimKey" value="'+c.key+'"><label class="field"><span>New reserve</span><input name="reserve" type="number" min="0" step="100" value="'+c.reserve+'"></label><button class="btn primary">Save reserve</button></form></section>':'');}
function billingPage(){const rows=state.invoices.map(i=>'<tr><td><strong>'+i.id+'</strong><small>'+esc(i.period)+'</small></td><td>'+esc(accountFor(i.accountId).name)+'</td><td>'+i.policyId+'</td><td>'+date(i.due)+'</td><td>'+cash(i.billed)+'</td><td>'+cash(i.paid)+'</td><td><strong>'+cash(i.billed-i.paid)+'</strong></td><td>'+badge(i.status)+'</td><td>'+(i.status==='Paid'?esc(i.method):btn('Record payment','payment:'+i.id,'small'))+'</td></tr>').join('');return head('BillingCenter','Invoices, installment plans, receipts and past-due follow-up.')+'<div class="grid cols3" style="margin-bottom:14px">'+stat('Open balance',whole(state.invoices.reduce((n,x)=>n+x.billed-x.paid,0)),'Across sample accounts')+stat('Past due',whole(state.invoices.filter(x=>x.status==='Past due').reduce((n,x)=>n+x.billed-x.paid,0)),'Follow-up required')+stat('Invoices',state.invoices.length,'Linked policy accounts')+'</div><section class="card"><div class="card-head"><div><h2>Invoice queue</h2><p>Payment changes update shared billing status and account activity.</p></div></div>'+table(['Invoice','Employer & period','Policy','Due date','Billed','Paid','Balance','Status','Action'],rows)+'</section><section class="grid cols2" style="margin-top:14px"><div class="card"><h2>Billing controls</h2><div class="list-item"><strong>Installment plans</strong><span>Monthly, quarterly and annual schedules</span></div><div class="list-item"><strong>Delinquency handling</strong><span>Reminder and notice review before cancellation action</span></div><div class="notice blue">A late invoice creates follow-up work. Cancellation requires notice timing and authorization controls.</div></div><div class="card"><h2>Audit adjustment handoff</h2><p class="small">Final audit changes appear as a separate BillingCenter transaction.</p>'+btn('Open Premium Audit','go:audits','small')+'</div></section>';}
function auditPage(){const auditor=['Premium Auditor','System Administrator'].includes(state.role);const rows=state.audits.map(a=>'<tr><td><strong>'+a.id+'</strong><small>'+a.type+'</small></td><td>'+esc(accountFor(a.accountId).name)+'</td><td>'+esc(a.period)+'</td><td>'+date(a.due)+'</td><td>'+badge(a.status)+'</td><td>'+cash(a.adjustment||0)+'</td><td>'+btn('Open','audit:'+a.id,'small')+'</td></tr>').join('');const a=state.audits.find(x=>x.id===state.activeAuditId)||state.audits[0];const employer=accountFor(a.accountId);const lines=a.entries.map((e,i)=>{const p=employer.payroll.find(x=>x.code===e.code);return '<tr><td>'+e.code+' · '+esc(p.description)+'</td><td>'+whole(e.estimated)+'</td><td><input data-audit-index="'+i+'" aria-label="Actual payroll '+e.code+'" type="number" min="0" step="100" value="'+e.actual+'" '+(auditor?'':'disabled')+'></td><td>'+whole((e.actual-e.estimated)*(p.rate||0)/100)+'</td></tr>';}).join('');const estimate=a.entries.reduce((n,e)=>n+D.manualPremium(e.estimated,employer.payroll.find(p=>p.code===e.code).rate,1),0);const actual=a.entries.reduce((n,e)=>n+D.manualPremium(e.actual,employer.payroll.find(p=>p.code===e.code).rate,1),0);const delta=D.auditAdjustment(estimate,actual);return head('Premium audit','Reconcile payroll by class code, verify supporting records and prepare premium adjustments.')+'<div class="grid cols3" style="margin-bottom:14px">'+stat('Open audits',state.audits.filter(x=>x.status==='In progress').length,'Audit work requiring review')+stat('Employer',esc(employer.name),'Selected audit account')+stat('Estimated adjustment',cash(delta),'Before finalization')+'</div><section class="card"><div class="card-head"><div><h2>Audit inventory</h2><p>PolicyCenter audit job and BillingCenter adjustment handoff</p></div></div>'+table(['Audit job','Employer','Period','Due','Status','Adjustment','Open'],rows)+'</section><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>'+a.id+' · '+a.type+'</h2><p>'+esc(employer.name)+' · '+esc(a.period)+'</p></div>'+badge(a.status)+'</div><div class="notice blue">'+esc(a.note)+'</div><p class="tiny">Evidence source: '+esc(a.source)+'</p><div class="toolbar" style="margin:10px 0">'+(auditor&&a.status!=='Completed'?btn('Finalize audit and create billing adjustment','finalize-audit:'+a.id,'primary small'):'')+'</div>'+table(['Classification','Estimated payroll','Actual payroll','Premium change'],lines)+'<div class="row" style="margin-top:12px"><span>Estimated manual premium '+whole(estimate)+' · audited manual premium '+whole(actual)+'</span><strong>'+cash(delta)+'</strong></div></section><p class="tiny">Guidewire PolicyCenter supports premium report and final audit jobs. These sample values are illustrative training records.</p>';}
function productsPage(){const admin=['Product Admin','System Administrator'].includes(state.role);const rows=state.products.classifications.map(x=>'<tr><td><strong>'+x.code+'</strong></td><td>'+esc(x.description)+'</td><td>'+cash(x.rate)+'</td><td>'+badge(x.active?'Active':'Inactive')+'</td></tr>').join('');const rules=state.products.rules.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.value)+'</td><td>'+esc(x.owner)+'</td><td>'+badge(x.status)+'</td></tr>').join('');return head('Product configuration','California product controls, classification references and rating assumptions.')+'<div class="grid cols3" style="margin-bottom:14px">'+stat('State',state.products.state,'Training product')+stat('Effective date',date(state.products.effective),'Product reference date')+stat('Classifications',state.products.classifications.length,'Configurable sample table')+'</div><section class="card"><div class="card-head"><div><h2>Classification and sample rates</h2><p>Training values in dollars per $100 of payroll</p></div></div>'+table(['Code','Phraseology','Sample rate / $100','Status'],rows)+(admin?'<form id="rateForm" class="toolbar" style="margin-top:12px"><label class="field"><span>Class code</span><select name="code">'+state.products.classifications.map(x=>'<option>'+x.code+'</option>').join('')+'</select></label><label class="field"><span>Sample rate</span><input name="rate" type="number" min="0" step=".01" required></label><button class="btn primary">Save training rate</button></form>':'<p class="tiny">Product changes are restricted to Product Admin.</p>')+'</section><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Underwriting and audit controls</h2><p>Effective-dated rules connected to role queues</p></div></div>'+table(['Control','Rule / check','Owner','Status'],rules)+'</section><div class="notice blue" style="margin-top:14px">California WCIRB phraseology is used for class codes 3632 and 8810. Rates in this workspace are illustrative only. Confirm assignments against employer operations and current approved rules.</div><p class="tiny">Sources: <a target="_blank" rel="noopener" href="https://www.wcirb.com/research-and-education/online-guide-workers%E2%80%99-compensation/standard-classification-system">WCIRB classification system</a> · <a target="_blank" rel="noopener" href="https://www.wcirb.com/research-and-education/online-guide-workers%E2%80%99-compensation/standard-classification-system/payroll-or-remuneration">Payroll or remuneration</a></p>';}
function qaPage(){const rows=state.qaResults||[];return head('QA workbench','Run consistency checks across role access, linked records and rating calculations.')+'<div class="grid cols4" style="margin-bottom:14px">'+stat('Checks available',7,'Deterministic local checks')+stat('Latest run',rows.length?rows.filter(x=>x.passed).length+'/'+rows.length:'Not run','Current workspace records')+stat('Failed checks',rows.filter(x=>!x.passed).length,'From most recent run')+stat('Run mode','Browser local','No external services')+'</div><section class="card"><div class="card-head"><div><h2>Workspace integrity suite</h2><p>Policy links, claim links, class rates and estimate arithmetic.</p></div><div class="toolbar">'+btn('Run checks','run-qa','primary')+btn('Reset sample data','reset-data','small')+'</div></div>'+(rows.length?rows.map(x=>'<div class="test-result row"><div><strong>'+esc(x.name)+'</strong><div class="tiny">'+esc(x.detail)+'</div></div>'+badge(x.passed?'Passed':'Failed')+'</div>').join(''):'<div class="notice blue">Select Run checks to inspect the current sample data.</div>')+'</section><section class="card" style="margin-top:14px"><h2>Test coverage</h2><div class="grid cols3" style="margin-top:12px"><div class="notice blue">PolicyCenter · Submissions, referrals, policy term, renewal and audits</div><div class="notice blue">ClaimCenter · First notice, assignment, status and return to work</div><div class="notice blue">BillingCenter · Invoices, payments and audit adjustments</div></div></section>';}
function alertsPage(){return head('Alerts and handoffs','Recent activity shared across the active role.')+'<section class="card">'+state.events.map(x=>'<div class="list-item"><div class="list-main"><strong>'+esc(x.title)+'</strong><span>'+esc(x.time)+' · '+esc(x.detail)+'</span></div>'+badge('Activity')+'</div>').join('')+'</section>';}
function payrollModal(){const a=account();return '<div class="modal-backdrop" id="modal"><section class="modal-card"><form id="payrollForm"><h2>Submit payroll update</h2><p class="tiny">Report current payroll by class. The premium auditor will see the update.</p><div class="formgrid">'+a.payroll.map((x,i)=>'<label class="field"><span>Actual payroll · '+x.code+' '+esc(x.description)+'</span><input type="number" min="0" step="100" name="p'+i+'" value="'+(x.actual||x.estimated)+'"></label>').join('')+'</div><div class="toolbar" style="margin-top:14px"><button class="btn primary">Submit report</button><button type="button" class="btn" data-action="close-modal">Cancel</button></div></form></section></div>';}
function injuryModal(){return '<div class="modal-backdrop" id="modal"><section class="modal-card"><form id="injuryForm"><h2>Report workplace injury</h2><p class="tiny">Employer first notice creates a connected ClaimCenter record.</p><div class="formgrid"><label class="field"><span>Worker name</span><input name="worker" required value="Rosa Alvarez"></label><label class="field"><span>Job title and class</span><input name="job" required value="CNC operator · 3632"></label><label class="field"><span>Date of injury</span><input name="injuryDate" type="date" value="'+TODAY+'" required></label><label class="field"><span>Severity</span><select name="severity"><option>Medical only</option><option>Lost time</option></select></label><label class="field full"><span>Incident description</span><textarea name="injury" required></textarea></label></div><div class="toolbar" style="margin-top:13px"><button class="btn primary">Create first notice</button><button type="button" class="btn" data-action="close-modal">Cancel</button></div></form></section></div>';}
function openSubmissionModal(){return '<div class="modal-backdrop" id="modal"><section class="modal-card"><form id="submissionForm"><h2>New workers compensation submission</h2><p class="tiny">Producer intake routed to underwriting.</p><div class="formgrid"><label class="field full"><span>Employer</span><select name="accountId">'+state.accounts.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select></label><label class="field"><span>Business operations</span><input name="operation" value="California wholesale distribution"></label><label class="field"><span>Estimated payroll</span><input name="payroll" type="number" min="0" value="920000"></label><label class="field"><span>Effective date</span><input name="effective" type="date" required value="2027-01-01"></label></div><div class="toolbar" style="margin-top:14px"><button class="btn primary">Submit</button><button type="button" class="btn" data-action="close-modal">Cancel</button></div></form></section></div>';}
function notifications(){return state.events.filter(x=>x.accountId===state.selectedAccountId).length;}
function render(){const app=$('#app');app.innerHTML=state.view==='welcome'?landing():shell();document.title=APP+(state.view==='welcome'?'':' · '+(navLabel(state.view)||'Alerts'));}
function openView(view){const allowed=rolesNav().map(x=>x[0]);state.view=allowed.includes(view)||view==='notifications'?'view-'+view:view;if(state.view.startsWith('view-'))state.view=state.view.slice(5);save();render();}function recordEvent(title,detail,accountId){push(title,detail,accountId);}
function newId(prefix){return prefix+'-'+Date.now().toString().slice(-6);}
function showModal(html){const old=$('#modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',html);}
function setView(view){state.view=view;save();render();}
document.addEventListener('click',event=>{
 const view=event.target.closest('[data-view]');if(view){event.preventDefault();open(view.dataset.view);return;}
 const roleCard=event.target.closest('[data-role-card]');if(roleCard){state.role=roleCard.dataset.roleCard;state.view='dashboard';save();render();return;}
 const target=event.target.closest('[data-action]');if(!target)return;
 const action=target.dataset.action;
 if(action==='open-workspace'){setView('dashboard');return;}
 if(action==='menu'){$('#sidebar').classList.toggle('open');return;}
 if(action==='close-modal'){$('#modal')?.remove();return;}
 if(action==='payroll'){showModal(payrollModal());return;}
 if(action==='report-injury'){showModal(injuryModal());return;}
 if(action==='new-submission'){showModal(openSubmissionModal());return;}
 if(action==='send-payroll'){recordEvent('Payroll update sent to producer','Employer submitted payroll by classification for renewal review.');save();toast('Payroll update sent to producer.');render();return;}
 if(action==='start-renewal'||action==='endorsement'){const a=account();const s={id:newId('SUB-2027'),accountId:a.id,type:action==='start-renewal'?'Renewal':'Policy change',producer:ROLES[state.role].name,received:TODAY,effective:a.renewal,status:'Submitted',priority:'Standard',referral:action==='start-renewal'?'Renewal application submitted for underwriting review':'Policy change request submitted for underwriting review',owner:'Marcus Reed',note:'Created from the active employer account.'};state.submissions.unshift(s);recordEvent(action==='start-renewal'?'Renewal submission created':'Policy change requested',s.id+' routed to underwriting.',a.id);state.view='submissions';save();render();toast('Work item routed to underwriting.');return;}
 if(action==='run-qa'){state.qaResults=D.runStaticChecks(state);save();render();return;}
 if(action==='reset-data'){state=clone(seed);save();render();toast('Sample workspace reset.');return;}
 if(action.startsWith('go:')){open(action.slice(3));return;}
 if(action.startsWith('account:')){state.selectedAccountId=action.slice(8);state.view='account';save();render();return;}
 if(action.startsWith('claim:')){state.activeClaimKey=action.slice(6);state.view='claims';save();render();return;}
 if(action.startsWith('audit:')){state.activeAuditId=action.slice(6);state.view='audits';save();render();return;}
 if(action.startsWith('submission-info:')){const s=state.submissions.find(x=>x.id===action.slice(16));if(s){s.status='Information requested';s.owner=ROLES[state.role].name;recordEvent('Underwriting information requested',s.id+': '+s.referral,s.accountId);}save();render();return;}
 if(action.startsWith('submission-clear:')){const s=state.submissions.find(x=>x.id===action.slice(17));if(s){s.status='Cleared to quote';s.owner=ROLES[state.role].name;s.referral='No unresolved referral';recordEvent('Submission cleared to quote',s.id+' cleared by underwriting.',s.accountId);}save();render();return;}
 if(action.startsWith('submission-decline:')){const s=state.submissions.find(x=>x.id===action.slice(19));if(s){s.status='Declined';s.owner=ROLES[state.role].name;recordEvent('Submission declined',s.id+' decision recorded by underwriting.',s.accountId);}save();render();return;}
 if(action.startsWith('submission-evidence:')){const s=state.submissions.find(x=>x.id===action.slice(20));if(s){s.status='Underwriter review';s.referral='Producer confirmed requested evidence is ready for review';s.owner='Marcus Reed';recordEvent('Producer evidence received',s.id+' returned to underwriting.',s.accountId);}save();render();return;}
 if(action.startsWith('claim-')){const [verb,key]=action.split(':');const c=state.claims.find(x=>x.key===key);if(c){if(verb==='claim-accept')c.status='Medical management';if(verb==='claim-rtw'){c.status='Modified duty';c.rtw='Modified duty confirmed by employer · '+date(TODAY);c.employerMessage='Modified-duty assignment confirmed and recorded.';}if(verb==='claim-close')c.status='Closed';c.events.unshift({date:TODAY,title:verb==='claim-close'?'Claim closed':verb==='claim-rtw'?'Modified duty confirmed':'Claim accepted for medical management',detail:'Updated by '+ROLES[state.role].name+'.'});recordEvent('Claim status updated',c.id+' · '+c.status,c.accountId);save();render();}return;}
 if(action.startsWith('payment:')){const i=state.invoices.find(x=>x.id===action.slice(8));if(i){i.paid=i.billed;i.status='Paid';i.method='Recorded in training workspace';recordEvent('Payment posted',i.id+' paid in full.',i.accountId);save();render();toast('Payment posted.');}return;}
 if(action.startsWith('finalize-audit:')){const a=state.audits.find(x=>x.id===action.slice(15));if(a&&a.status!=='Completed'&&['Premium Auditor','System Administrator'].includes(state.role)){const employer=accountFor(a.accountId);const estimated=a.entries.reduce((n,e)=>n+D.manualPremium(e.estimated,employer.payroll.find(x=>x.code===e.code).rate,1),0);const actual=a.entries.reduce((n,e)=>n+D.manualPremium(e.actual,employer.payroll.find(x=>x.code===e.code).rate,1),0);a.adjustment=D.auditAdjustment(estimated,actual);a.status='Completed';a.note='Audit finalized. Payroll reconciled; billing adjustment generated.';const amount=Math.max(0,a.adjustment);if(amount){state.invoices.unshift({id:newId('INV-AUDIT'),accountId:a.accountId,policyId:a.policyId,period:'Premium audit adjustment',billed:amount,paid:0,due:'2026-12-14',status:'Due',method:'Not paid'});}recordEvent('Premium audit finalized',a.id+' completed; '+(amount?'BillingCenter adjustment created.':'No additional premium due.'),a.accountId);save();render();toast('Audit completed and billing updated.');}return;}
});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.dataset.field==='role'){state.role=el.value;state.view='dashboard';save();render();}
 if(el.dataset.field==='account'){state.selectedAccountId=el.value;state.view='account';save();render();}
 if(el.dataset.auditIndex!==undefined){if(!['Premium Auditor','System Administrator'].includes(state.role))return;const a=state.audits.find(x=>x.id===state.activeAuditId);if(a){a.entries[Number(el.dataset.auditIndex)].actual=Number(el.value)||0;save();render();}}
});
document.addEventListener('submit',event=>{
 const form=event.target;event.preventDefault();const data=new FormData(form);
 if(form.id==='payrollForm'){const a=account();a.payroll.forEach((p,i)=>p.actual=Number(data.get('p'+i))||0);const audit=state.audits.find(x=>x.accountId===a.id&&x.status==='In progress');if(audit){audit.entries.forEach(e=>{const p=a.payroll.find(x=>x.code===e.code);if(p)e.actual=p.actual;});audit.source='Employer payroll update';}recordEvent('Employer payroll report submitted','Payroll by class code is available to premium audit and renewal review.',a.id);$('#modal')?.remove();save();render();toast('Payroll report shared with premium audit.');}
 if(form.id==='injuryForm'){const a=account(),p=policyFor(a.id),worker=String(data.get('worker')).trim();const key=newId('claim').toLowerCase();const claim={id:'WC-CL-2026-'+String(Date.now()).slice(-4),key,accountId:a.id,policyId:p.id,workerId:'worker-'+key,worker,job:String(data.get('job')),injuryDate:String(data.get('injuryDate')),injury:String(data.get('injury')),status:'New loss reported',severity:String(data.get('severity')),adjuster:'Unassigned',reserve:0,paid:0,lostDays:0,provider:'Pending assignment',rtw:'Awaiting initial work status',next:'Claims team to review first notice and confirm coverage.',employerMessage:'First notice was submitted and routed to the claims team.',workerMessage:'Your employer reported an injury. A claims representative will review the report.',events:[{date:TODAY,title:'Employer report received',detail:'First notice entered by '+ROLES[state.role].name+'.'}]};state.claims.unshift(claim);recordEvent('First notice of injury submitted',claim.id+' routed to ClaimCenter assignment.',a.id);$('#modal')?.remove();state.activeClaimKey=key;state.view='claims';save();render();toast('First notice routed to ClaimCenter.');}
 if(form.id==='submissionForm'){const id=newId('SUB-2027'),a=accountFor(String(data.get('accountId')));const s={id,accountId:a.id,type:'New business',producer:ROLES[state.role].name,received:TODAY,effective:String(data.get('effective')),status:'Submitted',priority:'Standard',referral:'Verify '+String(data.get('operation'))+' and payroll by classification ('+whole(Number(data.get('payroll')))+')',owner:'Marcus Reed',note:'Producer intake created in the training workspace.'};state.submissions.unshift(s);recordEvent('New business submission received',s.id+' routed to underwriting.',a.id);$('#modal')?.remove();state.selectedAccountId=a.id;state.view='submissions';save();render();toast('Submission sent to underwriting.');}
 if(form.id==='rateForm'){const code=String(data.get('code')),rate=Number(data.get('rate'));if(rate>=0){const item=state.products.classifications.find(x=>x.code===code);if(item)item.rate=rate;state.products.effective=TODAY;recordEvent('Product rate updated',code+' training rate set to '+cash(rate)+'.');save();render();toast('Training rate updated.');}}
 if(form.id==='reserveForm'){const c=state.claims.find(x=>x.key===state.activeClaimKey),reserve=Number(data.get('reserve'));if(c&&reserve>=0){c.reserve=reserve;recordEvent('Claim reserve updated',c.id+' reserve changed to '+whole(reserve)+'.',c.accountId);save();render();toast('Claim reserve updated.');}}
});
render();
